const seen = new Set();
const out = [];
for (const item of $input.all()) {
  const key = String(item.json.email ?? item.json.key ?? "").trim().toLowerCase();
  if (!key || seen.has(key)) continue;
  seen.add(key);
  out.push({ json: { ...item.json, email: item.json.email ? key : undefined } });
}
return out;
